  "GOLD_PILLOW": { name: "THE GOLDEN PILLOW", hex: "#E8A317", colour: "gold", danger: false, nouns: ["sleep"], text: "THE GOLDEN PILLOW: one plump square pillow in flat shiny gold (#E8A317) with four round tassels at its corners and one round gold medal on a short gold (#E8A317) ribbon hanging from its front." },
  "FISHING_ROD": { part: "the gold (#E8A317) star bait dangling from THE FISHING ROD", rest: "the rod itself stays quiet brown", name: "THE FISHING ROD", hex: "#E8A317", colour: "gold", danger: false, nouns: ["motivation"], text: "THE FISHING ROD: one long thin fishing rod in warm brown (#8B6A4E) with one string hanging from its tip, and one gold (#E8A317) star sticker dangling on the end of the string like a bait." },
